package com.tura.ventas.service;
import java.util.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import com.tura.ventas.modelo.CategoriaCliente; import com.tura.ventas.repositorio.CategoriaClienteRepository;
@Service public class CategoriaClienteService { private final CategoriaClienteRepository r; public CategoriaClienteService(CategoriaClienteRepository r){this.r=r;} public List<CategoriaCliente> listar(){return r.findAll();} public CategoriaCliente obtener(Integer id){return r.findById(id).orElseThrow();} @Transactional public CategoriaCliente guardar(CategoriaCliente c){if(c.getNombre()==null||c.getNombre().isBlank())throw new IllegalArgumentException("Ingrese el nombre de la categoría."); return r.save(c);} @Transactional public void eliminar(Integer id){r.deleteById(id);} }
